import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import 'package:intl/intl.dart';
import '../../data/app_database.dart';
import '../../models/app_models.dart';
import '../../services/gps_trip_service.dart';
import '../common/ui.dart';

class TripsScreen extends StatefulWidget { const TripsScreen({super.key}); @override State<TripsScreen> createState()=>_TripsScreenState(); }
class _TripsScreenState extends State<TripsScreen> {
  final gps=GpsTripService(); List<Vehicle> vehicles=[]; List<Trip> trips=[]; String? vehicleId; double distance=0; bool tracking=false; String? error; DateTime? started;
  Future<void> load() async {final db=AppDatabase.instance;final v=await db.vehicles();final t=await db.trips();if(mounted)setState((){vehicles=v;trips=t;if(vehicleId==null&&v.isNotEmpty)vehicleId=v.first.id;});}
  @override void initState(){super.initState();load();}
  @override void dispose(){gps.stop();super.dispose();}
  Future<void> start() async {try{await gps.start(onDistance:(d){if(mounted)setState(()=>distance=d);});if(mounted)setState((){tracking=true;error=null;distance=0;started=DateTime.now();});}catch(e){if(mounted)setState(()=>error=e.toString().replaceFirst('Exception: ',''));}}
  Future<void> stop() async {await gps.stop();final v=vehicles.where((x)=>x.id==vehicleId).firstOrNull;final startTime=started??DateTime.now();if(v!=null&&distance>0){final estimate=distance/v.referenceMileage;final trip=Trip(id:const Uuid().v4(),vehicleId:v.id,startedAt:startTime.toIso8601String(),distanceKm:distance,referenceMileage:v.referenceMileage,fuelPrice:v.fuelPrice,fuelLitres:estimate,fuelCost:estimate*v.fuelPrice,route:List.of(gps.points));await AppDatabase.instance.saveTrip(trip);}if(mounted)setState(()=>tracking=false);await load();}
  String vehicleName(String id)=>vehicles.where((v)=>v.id==id).map((v)=>v.name).firstOrNull??'Vehicle';
  void details(Trip t){final duration=DateTime.now().difference(DateTime.parse(t.startedAt));showModalBottomSheet(context:context,backgroundColor:const Color(0xFF12283D),builder:(ctx)=>Padding(padding:const EdgeInsets.all(22),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(vehicleName(t.vehicleId),style:const TextStyle(fontSize:21,fontWeight:FontWeight.bold)),const SizedBox(height:14),_detail('Started',DateFormat('dd MMM yyyy, hh:mm a').format(DateTime.parse(t.startedAt))),_detail('Distance', '${t.distanceKm.toStringAsFixed(2)} km'),_detail('GPS points','${t.route.length}'),_detail('Estimated fuel','${t.fuelLitres.toStringAsFixed(2)} L'),_detail('Estimated fuel cost','₹${t.fuelCost.toStringAsFixed(2)}'),const SizedBox(height:8),const Text('Fuel and mileage shown here are estimates based on the vehicle reference mileage. Use Fuel entries for measured full-tank mileage.',style:TextStyle(color:Colors.white60))])));}
  Widget _detail(String label,String value)=>Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(label,style:const TextStyle(color:Colors.white60)),Text(value,style:const TextStyle(fontWeight:FontWeight.w600))]));
  @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.fromLTRB(20,18,20,90),children:[const PageTitle('Trip tracking'),Panel(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Tracking status',style:TextStyle(color:Colors.white60)),const SizedBox(height:12),Text(tracking?'RECORDING':'IDLE',style:const TextStyle(fontSize:26,fontWeight:FontWeight.bold)),if(vehicles.isNotEmpty)DropdownButton<String>(value:vehicleId,isExpanded:true,items:vehicles.map((v)=>DropdownMenuItem(value:v.id,child:Text(v.name))).toList(),onChanged:tracking?null:(v)=>setState(()=>vehicleId=v)),const SizedBox(height:8),Text('Distance: ${distance.toStringAsFixed(2)} km',style:const TextStyle(fontSize:20)),if(error!=null)Padding(padding:const EdgeInsets.only(top:8),child:Text(error!,style:const TextStyle(color:Colors.orangeAccent))),const SizedBox(height:14),ElevatedButton(onPressed:vehicles.isEmpty?null:(tracking?stop:start),child:Text(tracking?'Stop and save trip':'Start trip')),const SizedBox(height:8),const Text('Keep the app open and this screen active during GPS recording. Trips are saved locally on this device.',style:TextStyle(color:Colors.white54))])),const SizedBox(height:24),const Text('Trip history',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:12),if(trips.isEmpty)const Panel(child:Text('No trips recorded yet. Start a trip to build your history.',style:TextStyle(color:Colors.white60))),...trips.map((t)=>Padding(padding:const EdgeInsets.only(bottom:12),child:Panel(child:ListTile(contentPadding:EdgeInsets.zero,title:Text('${t.distanceKm.toStringAsFixed(2)} km · estimated ${(t.distanceKm/t.fuelLitres).toStringAsFixed(1)} km/L'),subtitle:Text('${vehicleName(t.vehicleId)} · ${DateFormat('dd MMM yyyy, hh:mm a').format(DateTime.parse(t.startedAt))}'),onTap:()=>details(t),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{await AppDatabase.instance.deleteTrip(t.id);await load();})))))]);
}
